openpilot/selfdrive/carrot/signal_displa.content:
"""Opt-in visualization transport. Never read by the planner or control helpers."""
import json
import math
from pathlib import Path
import time

DISPLAY_FLAG = Path('/data/signal-color-shadow/display_enabled')
DISPLAY_PATH = Path('/dev/shm/carrot_signal_display.json')
STATUS_PATH = Path('/dev/shm/carrot_signal_display_status.json')
MAX_BYTES = 8192
MAX_AGE = .35
MAX_CAMERA_SKEW = .25
DISPLAY_HOLD = 2.0  # UI memory only; never extends the control observation lifetime.
SIZE = (1344, 760)


def display_requested(path=DISPLAY_FLAG):
  from openpilot.selfdrive.carrot.signal_mode import flag_override
  override = flag_override(path)
  if override is not None:
    return override
  try:
    return Path(path).read_text().strip() == '1'
  except OSError:
    return False


def publish_display(record, *, path=DISPLAY_PATH):
  tracks = [dict(id=t['id'], box=t['box'], state=t['state'], age=t['age'], raw=t['evidence']['raw'])
            for t in record['tracks'][:20]]
  payload = dict(version=1, stream='road', size=SIZE, frame_id=record['frame_id'],
                 timestamp=record['timestamp_eof'] / 1e9, session=record['session'],
                 engine=('neural_' + record['backend']) if record.get('neural') else
                        'trial' if record.get('revalidated') or record.get('daytime_comparison') else 'legacy',
                 tracks=tracks)
  text = json.dumps(payload, allow_nan=False)
  if len(text.encode()) > MAX_BYTES:
    raise ValueError('signal display payload too large')
  path = Path(path)
  temp = path.with_suffix('.tmp')
  temp.write_text(text)
  temp.replace(path)


def valid_record(record, now, camera_frame, *, hold=False):
  try:
    fid, timestamp, width, height, wide = camera_frame
    limit = DISPLAY_HOLD if hold else MAX_AGE
    skew = DISPLAY_HOLD if hold else MAX_CAMERA_SKEW
    return (not wide and (width, height) == SIZE and record['version'] == 1
            and record['stream'] == 'road' and record['size'] == list(SIZE)
            and 0 <= now - timestamp <= MAX_AGE and 0 <= now - record['timestamp'] <= limit
            and abs(timestamp - record['timestamp']) <= skew
            and abs(fid - record['frame_id']) <= (40 if hold else 5)
            and isinstance(record['session'], str) and bool(record['session'])
            and isinstance(record['tracks'], list) and len(record['tracks']) <= 20)
  except (KeyError, TypeError, ValueError, OverflowError):
    return False


def visible_tracks(record, now, camera_frame, *, hold=False):
  """Return current-image candidates only, in the road image's pixel coordinates."""
  try:
    if not valid_record(record, now, camera_frame, hold=hold):
      return ()
    _, _, width, height, _ = camera_frame
    tracks = record['tracks']
    if not isinstance(tracks, list) or len(tracks) > 20:
      return ()
    result = []
    for t in tracks:
      x1, y1, x2, y2 = t['box']
      if not (all(isinstance(v, (int, float)) and math.isfinite(v) for v in t['box'])
              and 0 <= x1 < x2 <= width and 0 <= y1 < y2 <= height
              and t['age'] == 0 and isinstance(t['id'], int) and 0 < t['id'] < 1_000_000):
        continue
      # Display current color evidence independently of departure qualification.
      # A green-first track cannot satisfy the observer's red-history gate.
      state = t['raw'] if t['raw'] in ('red', 'green') else 'unknown'
      confirmed = state != 'unknown' and t['state'] == state
      result.append(dict(id=t['id'], box=tuple(t['box']), state=state, confirmed=confirmed))
    return tuple(result)
  except (KeyError, TypeError, ValueError, OverflowError):
    return ()


class DisplayContinuity:
  """Bounded previous-result display. No permission or observer-state output."""
  def __init__(self):
    self.reset()

  def reset(self):
    self.key = None
    self.tracks = {}

  def update(self, record, now, camera_frame):
    if not valid_record(record, now, camera_frame, hold=True):
      self.reset()
      return ()
    key = (record['session'], record['timestamp'], record['frame_id'])
    if self.key and (key[0] != self.key[0] or key[1] < self.key[1] or key[2] < self.key[2]):
      self.reset()
    if key != self.key:
      current = visible_tracks(record, now, camera_frame, hold=True)
      current_ids = {t['id'] for t in current}
      inherited = {}
      # Neural inference can assign a new ID to the same housing. Preserve
      # display color through a unique geometric match, without renewing its
      # timestamp or changing any observer/control state.
      def same_housing(a, b):
        intersection = max(0, min(a[2], b[2])-max(a[0], b[0])) * max(0, min(a[3], b[3])-max(a[1], b[1]))
        union = (a[2]-a[0])*(a[3]-a[1]) + (b[2]-b[0])*(b[3]-b[1]) - intersection
        return intersection / max(union, 1) >= .5
      for t in current:
        if t['id'] in self.tracks or t['state'] != 'unknown':
          continue
        matches = [(tid, old) for tid, old in self.tracks.items() if tid not in current_ids
                   and now-old['color_time'] <= DISPLAY_HOLD and same_housing(old['track']['box'], t['box'])]
        if len(matches) == 1:
          tid, old = matches[0]
          if sum(same_housing(old['track']['box'], other['box']) for other in current) == 1:
            inherited[t['id']] = old
      # A replacement ID at the same housing must not leave a duplicate old color.
      for tid, old in list(self.tracks.items()):
        a = old['track']['box']
        if tid not in current_ids and any(
            max(a[0], t['box'][0]) < min(a[2], t['box'][2])
            and max(a[1], t['box'][1]) < min(a[3], t['box'][3]) for t in current):
          del self.tracks[tid]
      for t in current:
        previous = self.tracks.get(t['id'], inherited.get(t['id']))
        color_time = record['timestamp']
        if t['state'] == 'unknown' and previous and now - previous['color_time'] <= DISPLAY_HOLD:
          t = dict(t, state=previous['track']['state'], confirmed=False)
          color_time = previous['color_time']
        self.tracks[t['id']] = dict(track=t, observed=record['timestamp'], color_time=color_time, key=key)
      self.key = key
    fresh_ids = {t['id'] for t in visible_tracks(record, now, camera_frame)}
    result = []
    for tid, saved in sorted(self.tracks.items(), key=lambda item: -item[1]['observed']):
      if now - saved['observed'] > DISPLAY_HOLD:
        continue
      track = dict(saved['track'])
      # Unknown frames may preserve geometry, but never refresh an old color.
      if now - saved['color_time'] > DISPLAY_HOLD:
        track.update(state='unknown', confirmed=False)
      held = saved['key'] != key or tid not in fresh_ids or saved['color_time'] != saved['observed']
      track.update(held=held, age=now - saved['observed'])
      if held:
        track['confirmed'] = False
      result.append(track)
    result = result[:20]
    self.tracks = {t['id']: self.tracks[t['id']] for t in result}
    return tuple(result)


def project_box(box, video_rect):
  """Same full-image-to-destination mapping used by LiveRoadCamera.draw()."""
  x, y, w, h = video_rect
  x1, y1, x2, y2 = box
  return (x + x1 * w / SIZE[0], y + y1 * h / SIZE[1], (x2-x1) * w / SIZE[0], (y2-y1) * h / SIZE[1])


class SignalDisplayReader:
  def __init__(self, flag=DISPLAY_FLAG, path=DISPLAY_PATH):
    self.flag, self.path = Path(flag), Path(path)
    self.enabled = False
    self.next_flag_read = self.next_read = 0.
    self.record = None
    self._record_bytes = None
    self.next_status = 0.
    self.continuity = DisplayContinuity()
    self.held_count = 0

  def record_draw(self, camera_frame, count, *, path=STATUS_PATH, now=None):
    now = time.monotonic() if now is None else now
    if not self.enabled or now < self.next_status:
      return
    self.next_status = now + 1.
    try:
      record = self.record if isinstance(self.record, dict) else {}
      value = dict(display_revision=4, timestamp=now, boxes_drawn=count, held_boxes=self.held_count, camera_frame=camera_frame,
                   observation_frame=record.get('frame_id'), engine=record.get('engine'),
                   observation_timestamp=record.get('timestamp'))
      path = Path(path); temp = path.with_suffix('.tmp')
      temp.write_text(json.dumps(value, allow_nan=False)); temp.replace(path)
    except (OSError, ValueError, TypeError):
      pass

  def read(self, camera_frame, now=None):
    now = time.monotonic() if now is None else now
    if now >= self.next_flag_read:
      self.enabled = display_requested(self.flag)
      self.next_flag_read = now + .5
    if not self.enabled:
      self.record = None
      self._record_bytes = None
      self.continuity.reset()
      return ()
    if now >= self.next_read:
      self.next_read = now + .05
      try:
        with self.path.open('rb') as f:
          raw = f.read(MAX_BYTES + 1)
        if len(raw) > MAX_BYTES:
          self.record = self._record_bytes = None
        elif raw != self._record_bytes:
          self.record = json.loads(raw)
          self._record_bytes = raw
      except (OSError, ValueError):
        self.record = self._record_bytes = None
    tracks = self.continuity.update(self.record, now, camera_frame)
    self.held_count = sum(t['held'] for t in tracks)
    return tracks


class SignalStatusReader:
  """Camera-independent summary for HUDs, including cruise-inactive display.

  Previous color is UI memory for at most two seconds from capture. It is never
  published to the planner and a repeated packet cannot refresh that lifetime.
  """
  def __init__(self, path=DISPLAY_PATH):
    self.path = Path(path)
    self.next_read = 0.
    self.key = None
    self.color = 0
    self.color_time = -math.inf
    self.capture_time = -math.inf

  def read(self, now=None):
    now = time.monotonic() if now is None else now
    if not display_requested():
      self.key, self.color, self.color_time, self.capture_time = None, 0, -math.inf, -math.inf
      return 0, False, False
    if now >= self.next_read:
      self.next_read = now + .05
      try:
        with self.path.open('rb') as f:
          raw = f.read(MAX_BYTES+1)
        if len(raw) > MAX_BYTES:
          raise ValueError('oversize')
        record = json.loads(raw)
        stamp = record['timestamp']
        camera = (record['frame_id'], now, *SIZE, False)
        if not valid_record(record, now, camera, hold=True):
          raise ValueError('invalid display packet')
        key = (record['session'], stamp, record['frame_id'])
        if self.key and (key[0] != self.key[0] or key[1] < self.key[1] or key[2] < self.key[2]):
          self.color, self.color_time = 0, -math.inf
        if key != self.key:
          colors = {t['state'] for t in visible_tracks(record, now, camera, hold=True)}
          color = int('red' in colors) + 2*int('green' in colors)
          if color:
            self.color, self.color_time = color, stamp
          self.key, self.capture_time = key, stamp
      except (OSError, ValueError, TypeError, KeyError, OverflowError):
        self.key, self.color, self.color_time, self.capture_time = None, 0, -math.inf, -math.inf
    color = self.color if 0 <= now-self.color_time <= DISPLAY_HOLD else 0
    held = bool(color and (now-self.color_time > MAX_AGE or self.color_time != self.capture_time))
    return color, held, 0 <= now-self.capture_time <= DISPLAY_HOLD


_status_reader = SignalStatusReader()


def signal_display_status():
  return _status_reader.read()

openpilot/selfdrive/carrot/signal_road_p.content:
"""Suspend signal-specific control only on a fresh, explicit vNavi road class."""
import time

NAVI_TIMEOUT = 2.0
ROAD_TIMEOUT = 10.0  # v2 JSON stream's advertised stale_timeout_ms


def signal_detection_suspended(sm, now=None):
  now = time.monotonic() if now is None else now
  try:
    if not (sm.seen['carrotNavi'] and sm.valid['carrotNavi'] and sm.alive['carrotNavi']):
      return False
    if not 0 <= now - sm.recv_time['carrotNavi'] <= NAVI_TIMEOUT:
      return False
    navi = sm['carrotNavi']
    lane = navi.laneCurrent
    if navi.schemaVersion != 1 or not navi.connected or not navi.sessionId:
      return False
    if navi.navigationStatus.meta.present and navi.navigationStatus.offRoute:
      return False
    # roadCategory defaults to zero in old messages and when the source omits it.
    # Neither case is evidence of a motorway.
    return bool(lane.meta.present and lane.roadCategoryValid and lane.roadCategory in (0, 1)
                and lane.meta.receivedMonoTimeNanos > 0
                and 0 <= now - lane.meta.receivedMonoTimeNanos / 1e9 <= ROAD_TIMEOUT)
  except (AttributeError, KeyError, TypeError):
    return False

openpilot/selfdrive/carrot/signal_start_.content:
"""Opt-in stopped-car red veto, separate from moving signal assistance.

Image position is only a forward-signal hypothesis, not ego-lane association.
Unknown/stale observations cannot release a latched stop. A confirmed red-to-green
transition may feed the normal departure state machine, with driver gates intact.
"""
from dataclasses import dataclass, asdict
import json
import math
from pathlib import Path
import time

from openpilot.selfdrive.carrot.signal_assist_runtime import SignalAssistRuntime, requested, MAX_BYTES

ENABLE_PATH = Path('/data/signal-color-shadow/start_guard_enabled')
OBSERVATION_PATH = Path('/dev/shm/carrot_signal_start_observation.json')


def observation_color(observation, now, *, enabled, valid, drive):
  """Display-only current evidence: 0 unknown, 1 red, 2 green, 3 mixed.

  Never reuse the stop latch or UI memory as a current color observation.
  """
  if not (enabled and valid and drive) or observation is None:
    return 0
  try:
    stamp = observation['timestamp']
    if not math.isfinite(now) or not math.isfinite(stamp) or not 0 <= now-stamp <= SignalStartGuard.MAX_AGE:
      return 0
    colors = {t['raw'] for t in observation['tracks'] if SignalStartGuard.front(t['box'])}
    return int('red' in colors) + 2*int('green' in colors)
  except (KeyError, TypeError, ValueError):
    return 0


def publish_start_observation(record, directory=ENABLE_PATH.parent, path=OBSERVATION_PATH):
  if not requested(Path(directory) / ENABLE_PATH.name):
    return
  tracks = []
  for t in record['tracks'][:20]:
    raw = t.get('evidence', {}).get('raw', 'unknown')
    if record.get('neural'):
      labels = t.get('label', '').split(',')
      raw = ('red' if 'red' in labels else 'green' if labels == ['green'] else 'unknown')
      score = t.get('score', 0)
      if not math.isfinite(score) or not .8 <= score <= 1. or not 0 <= t.get('neural_age', math.inf) <= .5:
        raw = 'unknown'
    elif t.get('observations', 0) < 3:
      raw = 'unknown'
    if t.get('age') != 0:
      raw = 'unknown'
    tracks.append(dict(box=t['box'], raw=raw, id=t.get('id'),
                       seen_red=bool(t.get('seen_red', False)) and not record.get('neural', False)))
  obj = dict(version=1, stream='road', size=[1344, 760], session=record['session'],
             frame_id=record['frame_id'], timestamp=record['timestamp_eof']/1e9, tracks=tracks)
  data = json.dumps(obj, allow_nan=False)
  if len(data.encode()) > MAX_BYTES:
    raise ValueError('start observation too large')
  path = Path(path)
  tmp = path.with_suffix('.tmp')
  tmp.write_text(data)
  tmp.replace(path)


@dataclass(frozen=True)
class StartDecision:
  hold: bool = False
  warn: bool = False
  released: bool = False
  reason: str = 'disabled'
  green_confirmed: bool = False


class SignalStartGuard:
  # Distinct from the old moving assist's 200 ms deadline: measured QCOM
  # capture-to-result is 335 ms mean / 400 ms max in the parked trial.
  MAX_AGE = .65
  MAX_GAP = .7

  def __init__(self):
    self.reset()
    self.last_now = -math.inf
    self.cooldown = -math.inf

  def reset(self):
    self.hold = False
    self.warned = False
    self.session = None
    self.box = None
    self.frame = -1
    self.timestamp = -math.inf
    self.pending = None
    self.since = 0.
    self.count = 0
    self.red_anchors = []
    self.track_id = None
    self.release_authorized = False
    self.green_evidence = False

  def reset_votes(self):
    self.green_evidence = False
    self.pending, self.count = None, 0
    for anchor in self.red_anchors:
      anchor['pending'], anchor['count'] = None, 0

  def observe_group(self, tracks, timestamp, gap):
    """A central red-to-green transition may resolve a lost primary.

    Green never moves an anchor. Duplicate/overlapping detections cannot become
    two votes. Conflicting reds veto release except a much smaller/lower group
    separated from TWO independently confirmed overhead transitions.
    Outside the central image band, keep the existing two-housing fallback.
    """
    reds = [t for t in tracks if t['raw'] == 'red']
    for track in reds:
      if len(self.red_anchors) < 8 and not any(self.anchor_matches(a['box'], a.get('id'), track) for a in self.red_anchors):
        self.red_anchors.append({'box': list(track['box']), 'id': track.get('id'), 'red': False, 'pending': None, 'count': 0, 'since': timestamp})
    greens = []
    for anchor in self.red_anchors:
      matches = [t for t in tracks if self.anchor_matches(anchor['box'], anchor.get('id'), t)]
      color = matches[0]['raw'] if len(matches) == 1 else 'unknown'
      if color == 'green' and (not anchor['red'] or any(
          not self.separate_lower_red(t['box'], anchor['box'], anchor['box']) for t in reds)):
        color = 'unknown'
      if color not in ('red', 'green') or color != anchor['pending'] or gap > self.MAX_GAP:
        anchor.update(pending=color, since=timestamp, count=1)
      else:
        anchor['count'] += 1
      if color == 'red':
        anchor['box'] = list(matches[0]['box'])
        anchor['id'] = matches[0].get('id')
        if anchor['count'] >= 2 and timestamp-anchor['since'] >= .15-1e-9:
          anchor['red'] = True
      elif color == 'green' and anchor['count'] >= 3 and timestamp-anchor['since'] >= .7-1e-9:
        greens.append(anchor['box'])
    # Image-centre support is a hypothesis, not signal-to-lane assignment.
    # Each candidate already needs its own confirmed red history and fresh
    # same-box green streak; a newly appearing green cannot release the stop.
    if not reds and any(.45 <= (box[0]+box[2])/2688 <= .55 for box in greens):
      return 'green_transition'
    for i, a in enumerate(greens):
      for b in greens[i+1:]:
        # Disjoint housings, comparable size and row: not two fits to one lamp.
        aw, bw = a[2]-a[0], b[2]-b[0]
        if (min(a[2], b[2]) <= max(a[0], b[0]) and max(aw, bw) <= 2*min(aw, bw)
            and abs((a[1]+a[3]-b[1]-b[3])/2) <= max(a[3]-a[1], b[3]-b[1])
            and all(self.separate_lower_red(t['box'], a, b) for t in reds)):
          return 'green_group'
    return None

  @staticmethod
  def separate_lower_red(red, a, b):
    """Only a paired overhead transition may exclude much smaller/lower reds.

    This is an image grouping hypothesis, not metric distance or lane assignment.
    A same-row, larger, overlapping, or insufficiently separated red still wins.
    """
    width = min(a[2]-a[0], b[2]-b[0])
    height = min(a[3]-a[1], b[3]-b[1])
    return (red[2]-red[0] <= .7*width and red[3]-red[1] <= .7*height
            and red[1] >= max(a[3], b[3]) + 2*max(a[3]-a[1], b[3]-b[1]))

  @classmethod
  def anchor_matches(cls, box, track_id, track):
    other = track['box']
    if cls.matches(box, other):
      return True
    # Same producer/session identity plus red history can bridge bounded box
    # resizing. Green cannot walk the fixed red reference onto a new housing.
    if (not isinstance(track_id, int) or isinstance(track_id, bool) or track.get('id') != track_id
        or not track.get('seen_red', False)):
      return False
    w, h = box[2]-box[0], box[3]-box[1]
    ow, oh = other[2]-other[0], other[3]-other[1]
    inter = max(0, min(box[2], other[2])-max(box[0], other[0])) * max(0, min(box[3], other[3])-max(box[1], other[1]))
    return (.5 <= ow*oh/(w*h) <= 2. and inter/(w*h+ow*oh-inter) >= .4
            and abs((box[0]+box[2]-other[0]-other[2])/2) <= .25*w
            and abs((box[1]+box[3]-other[1]-other[3])/2) <= .25*h)

  @staticmethod
  def front(box):
    try:
      a, b, c, d = box
      return (all(math.isfinite(v) for v in box) and 0 <= a < c <= 1344 and 0 <= b < d <= 760
              and .3 <= (a+c)/2688 <= .75 and .08 <= (b+d)/1520 <= .55)
    except (TypeError, ValueError):
      return False

  @staticmethod
  def matches(a, b):
    intersection = max(0, min(a[2], b[2])-max(a[0], b[0])) * max(0, min(a[3], b[3])-max(a[1], b[1]))
    area_a, area_b = (a[2]-a[0])*(a[3]-a[1]), (b[2]-b[0])*(b[3]-b[1])
    return intersection / (area_a+area_b-intersection) >= .6

  def observe(self, now, observation):
    if not observation:
      return 'missing'
    try:
      ts, fid, session = observation['timestamp'], observation['frame_id'], observation['session']
      if not math.isfinite(ts) or not 0 <= now-ts <= self.MAX_AGE:
        self.reset_votes()
        return 'stale_or_future'
      if not isinstance(fid, int) or not isinstance(session, str) or not session:
        raise ValueError('invalid identity')
      if session != self.session:
        # A restart cannot inherit green release rights; reacquire red first.
        self.session, self.box, self.track_id = session, None, None
        self.release_authorized = self.green_evidence = False
        self.timestamp, self.frame = -math.inf, -1
        self.pending, self.count = None, 0
        self.red_anchors = []
      if ts <= self.timestamp or fid <= self.frame:
        return 'repeated_or_reordered'
      gap = ts-self.timestamp
      self.timestamp, self.frame = ts, fid
      tracks = [t for t in observation['tracks'] if self.front(t['box'])]
      group_green = self.observe_group(tracks, ts, gap)
      matches = [t for t in tracks if self.box is not None and self.anchor_matches(self.box, self.track_id, t)]
      red = [t for t in tracks if t['raw'] == 'red']
      if self.box is None or (not matches and red):
        selected = min(red, key=lambda t: abs((t['box'][0]+t['box'][2])/2688-.5)) if red else None
        if selected is not None:
          self.box = selected['box']
          self.track_id = selected.get('id')
          self.pending, self.count = None, 0
      else:
        # Ambiguous overlapping objects, another red, or a lost housing must
        # not grant green release. Keep the fixed red anchor while stopped.
        red_matches = [t for t in matches if t['raw'] == 'red']
        selected = red_matches[0] if red_matches else matches[0] if len(matches) == 1 else None
      color = selected['raw'] if selected is not None else 'unknown'
      if color == 'red':
        # Settle camera pitch/box jitter using fresh red only. A green box
        # cannot walk the reference onto a neighboring lamp.
        self.box = selected['box']
        self.track_id = selected.get('id')
      if color == 'green' and red:
        color = 'unknown'
      if group_green:
        return group_green
      if color not in ('red', 'green') or color != self.pending or gap > self.MAX_GAP:
        self.pending, self.since, self.count = color, ts, 1
      else:
        self.count += 1
      if color == 'red' and self.count >= 2 and ts-self.since >= .15-1e-9:
        return 'red'
      if color == 'green' and self.count >= 3 and ts-self.since >= .7-1e-9:
        return 'green'
      return 'unconfirmed'
    except (KeyError, TypeError, ValueError, OverflowError):
      self.reset_votes()
      return 'malformed'

  def update(self, now, observation, *, enabled, valid, drive, gas, speed, departure):
    if not enabled or not drive:
      self.reset()
      self.last_now = now if math.isfinite(now) else -math.inf
      return StartDecision()
    if gas:
      self.reset()
      self.last_now = now if math.isfinite(now) else -math.inf
      self.cooldown = now+10. if math.isfinite(now) else math.inf
      return StartDecision(reason='driver_gas')
    if not math.isfinite(now) or now < self.last_now:
      # Clock discontinuity cannot turn a held red into permission to go.
      self.pending, self.count, self.box, self.session = None, 0, None, None
      self.red_anchors = []
      self.release_authorized = self.green_evidence = False
      return StartDecision(self.hold, reason='clock_discontinuity')
    self.last_now = now
    if now < self.cooldown:
      return StartDecision(reason='driver_cooldown')
    if not valid or not math.isfinite(speed):
      self.reset_votes()
      return StartDecision(self.hold, reason='invalid_context')
    if not self.hold and abs(speed) > .3 and not (self.release_authorized and abs(speed) < 5/3.6):
      self.reset()
      return StartDecision(reason='moving_no_entry')
    evidence = self.observe(now, observation)
    released = False
    if evidence != 'repeated_or_reordered':
      self.green_evidence = evidence in ('green', 'green_group', 'green_transition')
    if evidence == 'red':
      self.release_authorized = False
      self.hold = self.hold or abs(speed) <= .3
    elif evidence in ('green', 'green_group', 'green_transition') and self.hold:
      released = True
      # Keep the fixed red anchors while stopped so the same fresh paired
      # transition continues to exclude a separate lower red group. Missing
      # green removes that exclusion; moving/disable/restart clears identity.
      self.hold = self.warned = False
      self.release_authorized = True
    warn = self.hold and departure and not self.warned
    self.warned |= warn
    green = (self.release_authorized and self.green_evidence and not self.hold
             and 0 <= now-self.timestamp <= self.MAX_AGE)
    return StartDecision(self.hold, warn, released, evidence, green)


class SignalStartRuntime(SignalAssistRuntime):
  def __init__(self, enable_path=ENABLE_PATH, observation_path=OBSERVATION_PATH):
    super().__init__(enable_path, observation_path)
    self.guard = SignalStartGuard()  # mode 0 may be enabled later without restart

  def record(self, decision, speed, distance):
    if not self.enabled and self.last_decision is None:
      return
    now = time.monotonic()
    key = (decision.hold, decision.warn, decision.released, decision.reason, decision.green_confirmed)
    if key != self.last_decision or now-self.last_log >= 1:
      from openpilot.common.swaglog import cloudlog
      cloudlog.event('signalStartGuard', **asdict(decision), speed=float(speed),
                     model_stop_distance=float(distance), enabled=self.enabled)
      self.last_decision, self.last_log = key, now

